 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Diagonal runs of at least two identical non-background cells are rays;
    # extend each ray through the background, stopping at another colored cell
    # or the edge.
    directions = ((1, 1), (1, -1))
    for dr, dc in directions:
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w) or grid[r2][c2] != color:
                    continue
                # Extend both ends of this matching diagonal pair.
                for sr, sc in ((-dr, -dc), (dr, dc)):
                    rr, cc = r, c
                    while 0 <= rr + sr < h and 0 <= cc + sc < w:
                        rr += sr
                        cc += sc
                        if grid[rr][cc] != bg:
                            break
                        out[rr][cc] = color
    return out
